def precedence(op):
    if op == '^':
        return 3
    elif op in '*/%':
        return 2
    elif op in '+-':
        return 1
    return 0
def infix_to_prefix(expression):
    expression = expression[::-1]
    expression = ''.join(')' if c == '(' else '(' if c == ')' else c
                         for c in expression)
    stack = []
    result = ""
    for char in expression:
        if char.isalnum():
            result += char
        elif char == '(':
            stack.append(char)
        elif char == ')':
            while stack and stack[-1] != '(':
                result += stack.pop()
            if stack:
                stack.pop()
        else:
            while (stack and stack[-1] != '(' and
                   precedence(stack[-1]) > precedence(char)):
                result += stack.pop()
            stack.append(char)
    while stack:
        result += stack.pop()
    return result[::-1]
